<template>
  <div class="manager-page"><div class="page-heading"><div><div class="eyebrow">PROFILE</div><h1>个人资料</h1><p>维护你的公开信息与头像。</p></div></div><div class="profile-grid"><div class="card avatar-card"><el-upload :action="uploadUrl" :show-file-list="false" :on-success="uploadSuccess"><div class="big-avatar"><img :src="form.avatar || fallback" alt=""><span><el-icon><Camera /></el-icon></span></div></el-upload><h3>{{form.name}}</h3><p>@{{form.username}}</p><el-tag>{{roleText}}</el-tag></div><div class="card form-card"><el-form :model="form" label-position="top"><el-form-item label="账号"><el-input v-model="form.username" disabled/></el-form-item><el-form-item label="姓名"><el-input v-model="form.name"/></el-form-item><el-form-item label="角色"><el-input :model-value="roleText" disabled/></el-form-item><el-button type="primary" round @click="save">保存资料</el-button></el-form></div></div></div>
</template>
<script setup>
import {reactive,computed,onMounted} from 'vue';import request from '@/utils/request';import {ElMessage} from 'element-plus';const user=JSON.parse(localStorage.getItem('system-user')||'{}');const form=reactive({...user});const uploadUrl=import.meta.env.VITE_BASE_URL+'/files/upload';const api=()=>user.role==='TEACHER'?'/teacher':'/admin';const fallback='/images/avatars/'+(user.role==='TEACHER'?'teacher':'admin')+'.svg';const roleText=computed(()=>user.role==='TEACHER'?'书院教师':'系统管理员');const load=()=>request.get(`${api()}/selectById/${user.id}`).then(res=>{if(res.code==='200')Object.assign(form,res.data||{})});const uploadSuccess=res=>{if(res.code==='200'){form.avatar=res.data;save()}};const save=()=>request.put(`${api()}/update`,{...form,password:''}).then(res=>{if(res.code==='200'){localStorage.setItem('system-user',JSON.stringify(form));Object.assign(user,form);ElMessage.success('资料已更新')}else ElMessage.error(res.msg)});onMounted(load)
</script>
<style scoped>.profile-grid{display:grid;grid-template-columns:320px 1fr;gap:20px}.avatar-card{text-align:center;padding:36px}.big-avatar{position:relative;width:130px;height:130px;margin:0 auto 16px;cursor:pointer}.big-avatar img{width:100%;height:100%;border-radius:50%;object-fit:cover;border:4px solid #fff;box-shadow:0 15px 35px rgba(20,33,61,.18)}.big-avatar span{position:absolute;right:5px;bottom:5px;width:32px;height:32px;border-radius:50%;background:var(--primary);color:#fff;display:grid;place-items:center}.avatar-card h3{font-family:var(--font-serif);margin:0 0 6px}.avatar-card p{color:var(--muted);font-size:12px;margin:0 0 14px}.form-card{padding:30px;max-width:650px}.form-card .el-button{width:150px}@media(max-width:800px){.profile-grid{grid-template-columns:1fr}}
</style>
